const EARLIER_EXERCISES = [
 {id:'w6-code-01',topic:'recursion',name:'Continue the recursive countdown',task:'Complete the indented recursive call so the positive integer n becomes smaller by one.',before:'def countdown(n):\n    if n <= 0:\n        print("Launch")\n        return\n    print(n)',after:'\ncountdown(3)',answers:['countdown(n - 1)'],hint:'Call the same function with n - 1.',explanation:'The calls use 3, 2, 1, and 0. The base case prints Launch. Expected output: 3, 2, 1, Launch on separate lines.',program:'w6-01',indent:4},
 {id:'w6-code-02',topic:'recursion',name:'Return the factorial recurrence',task:'Complete the recursive return for a nonnegative integer n.',before:'def factorial_recursive(n):\n    if n == 0:\n        return 1',after:'\nprint(factorial_recursive(5))  # 120',answers:['return n * factorial_recursive(n - 1)','return factorial_recursive(n - 1) * n'],hint:'n! = n × (n − 1)!',explanation:'Each call reduces n by one. The multiplication unwinds from the base value 1. For n = 5, the result is 120.',program:'w6-02',indent:4},
 {id:'w6-code-03',topic:'while',name:'Find the bisection midpoint',task:'Complete the assignment to midpoint using left and right.',before:'left = 0.0\nright = 3.0',after:'print(midpoint)  # 1.5',answers:['midpoint = (left + right) / 2','midpoint = (right + left) / 2'],hint:'Average the two bracket endpoints.',explanation:'Bisection tests the midpoint of the current bracket. (0.0 + 3.0) / 2 = 1.5. The full example uses a height residual to choose the next bracket.',program:'w6-03',indent:0},
 {id:'w6-code-04',topic:'recursion',name:'Combine the two Fibonacci calls',task:'Use both previous terms in the recursive return. This lecture example defines F(0) = F(1) = 1.',before:'def fibonacci(n):\n    if n == 0 or n == 1:\n        return 1',after:'\nprint(fibonacci(5))  # 8',answers:['return fibonacci(n - 1) + fibonacci(n - 2)','return fibonacci(n - 2) + fibonacci(n - 1)'],hint:'Add the values for n − 1 and n − 2.',explanation:'The lecture sequence is 1, 1, 2, 3, 5, 8. Always inspect the stated base cases: some practice programs instead use 0 and 1.',program:'w6-04',indent:4},
 {id:'w6-code-05',topic:'strings',name:'Check a palindrome recursively',task:'Return True only when the end characters match and the interior is a palindrome.',before:'def is_palindrome(text):\n    if len(text) <= 1:\n        return True',after:'\nprint(is_palindrome("level"))  # True',answers:['return text[0] == text[-1] and is_palindrome(text[1:-1])','return (text[0] == text[-1] and is_palindrome(text[1:-1]))'],hint:'Use text[0], text[-1], the slice text[1:-1], and and.',explanation:'The base case handles empty and one-character strings before indexing. Matching outer characters are removed by the slice. A mismatch short-circuits the recursive call.',program:'w6-05',indent:4},
 {id:'w6-code-06',topic:'recursion',name:'Accumulate a recursive list sum',task:'Return the first element plus the recursive sum of the remaining list.',before:'def recursive_sum(values):\n    if len(values) == 0:\n        return 0',after:'\nprint(recursive_sum([2.0, 3.5, 4.0]))  # 9.5',answers:['return values[0] + recursive_sum(values[1:])','return recursive_sum(values[1:]) + values[0]'],hint:'The tail of the list is values[1:].',explanation:'The recursion adds 2.0 + 3.5 + 4.0 + 0. Slicing produces smaller lists and leaves the original list unchanged.',program:'w6-06',indent:4},
 {id:'w6-code-07',topic:'dicts',name:'Save a snapshot of dictionary keys',task:'Use list() to save the current keys in saved_keys before the dictionary is updated.',before:'working = {"steel": 7850, "aluminum": 2700}',after:'working["copper"] = 8960\nprint(saved_keys)  # [\'steel\', \'aluminum\']',answers:['saved_keys = list(working.keys())','saved_keys = list(working)'],hint:'A list stores a snapshot; keys() alone gives a live view.',explanation:'The saved list retains the two original keys. A dictionary keys view would also reflect the later copper entry.',program:'w6-07',indent:0},
 {id:'w6-code-08',topic:'dicts',name:'Count each material sample',task:'Update counts[material] with its old count plus one. Use get() with default 0.',before:'samples = ["Cu", "Al", "Cu"]\ncounts = {}\nfor material in samples:',after:'print(counts)  # {\'Cu\': 2, \'Al\': 1}',answers:['counts[material] = counts.get(material, 0) + 1','counts[material] = 1 + counts.get(material, 0)'],hint:'counts.get(material, 0) supplies zero for a new material.',explanation:'The first Cu sets the count to 1, Al starts at 1, and the next Cu increases its existing count to 2.',program:'w6-08',indent:4},
 {id:'w6-code-09',topic:'dicts',name:'Convert a nested material property',task:'Read yield_strength_pa from record and convert Pa to MPa in strength_mpa.',before:'record = {"yield_strength_pa": 250e6}',after:'print(strength_mpa)  # 250.0',answers:['strength_mpa = record["yield_strength_pa"] / 1e6','strength_mpa = record["yield_strength_pa"] / 1000000'],hint:'One MPa equals 1,000,000 Pa.',explanation:'250 × 10^6 Pa divided by 10^6 Pa/MPa gives 250.0 MPa. The dictionary continues to store the original value in Pa.',program:'w6-09',indent:0},
 {id:'w6-code-10',topic:'recursion',name:'Count warnings with recursion',task:'Return the contribution of this reading plus the recursive count for the remaining readings.',before:'def count_above_recursive(readings, limit):\n    if len(readings) == 0:\n        return 0\n    if readings[0] > limit:\n        first_count = 1\n    else:\n        first_count = 0',after:'\nprint(count_above_recursive([79.0, 80.0, 81.0], 80.0))  # 1',answers:['return first_count + count_above_recursive(readings[1:], limit)','return count_above_recursive(readings[1:], limit) + first_count'],hint:'Keep the same limit and pass readings[1:] to the next call.',explanation:'The strict > comparison counts only 81.0. A reading exactly at 80.0 contributes zero. The full sensor example checks these boundary cases.',program:'w6-10',indent:4}
];
